chunk_t * get_connection_ppk ( const struct connection * c , chunk_t * * ppk_id ) { struct secret * s = lsw_get_secret ( c , SECRET_PPK , false ) ; if ( s == NULL ) { return NULL ; } struct secret_stuff * pks = get_secret_stuff ( s ) ; * ppk_id = & pks -> ppk_id ; if ( DBGP ( DBG_CRYPT ) ) { DBG_log ( "Found PPK" ) ; DBG_dump_hunk ( "PPK_ID:" , * * ppk_id ) ; DBG_dump_hunk ( "PPK:" , pks -> ppk ) ; } return & pks -> ppk ; } 